function shouldRefresh(entry, now, beta = 1) {
  const jitter = entry.delta * beta * Math.log(Math.random());
  return now + jitter >= entry.expiry;
}

async function release(key, token) {
  const current = await redis.get(key);
  if (current === token) {
    await redis.del(key);
  }
}

